#include "stock_native_detached_turret_launch.hpp"
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace stock_native_detached_turret {
namespace {
Point position(const Point&o,const Point&v,double t){return {{o[0]+v[0]*t,o[1]+v[1]*t-.5*9.81*t*t,o[2]+v[2]*t}};}
Point velocity(const Point&v,double t){return {{v[0],v[1]-9.81*t,v[2]}};}
double energy(const Point&v){return .5*(v[0]*v[0]+v[1]*v[1]+v[2]*v[2]);}
void finite(const Point&p){for(auto v:p)if(!std::isfinite(v))throw std::invalid_argument("Detached launch vector is nonfinite");}
std::uint32_t rotl(std::uint32_t x,unsigned n){return (x<<n)|(x>>(32-n));}
std::uint32_t seed(const std::string&value){
    std::vector<std::uint8_t> bytes(value.begin(),value.end());const std::uint64_t bits=bytes.size()*8ull;bytes.push_back(0x80);while(bytes.size()%64!=56)bytes.push_back(0);for(int i=7;i>=0;--i)bytes.push_back(std::uint8_t(bits>>(8*i)));std::uint32_t h0=0x67452301u,h1=0xefcdab89u,h2=0x98badcfeu,h3=0x10325476u,h4=0xc3d2e1f0u;
    for(std::size_t offset=0;offset<bytes.size();offset+=64){std::uint32_t w[80]{};for(unsigned i=0;i<16;++i)for(unsigned j=0;j<4;++j)w[i]=(w[i]<<8)|bytes[offset+4*i+j];for(unsigned i=16;i<80;++i)w[i]=rotl(w[i-3]^w[i-8]^w[i-14]^w[i-16],1);auto a=h0,b=h1,c=h2,d=h3,e=h4;for(unsigned i=0;i<80;++i){std::uint32_t f,k;if(i<20){f=(b&c)|((~b)&d);k=0x5a827999u;}else if(i<40){f=b^c^d;k=0x6ed9eba1u;}else if(i<60){f=(b&c)|(b&d)|(c&d);k=0x8f1bbcdcu;}else{f=b^c^d;k=0xca62c1d6u;}const auto temp=rotl(a,5)+f+e+k+w[i];e=d;d=c;c=rotl(b,30);b=a;a=temp;}h0+=a;h1+=b;h2+=c;h3+=d;h4+=e;}return h0&0x7fffffffu;
}
Point transformed(const Point&p,const Point&a){const auto sr=std::sin(a[2]),cr=std::cos(a[2]),sp=std::sin(a[1]),cp=std::cos(a[1]),sy=std::sin(a[0]),cy=std::cos(a[0]);Point r{{cr*p[0]-sr*p[1],sr*p[0]+cr*p[1],p[2]}};Point t{{r[0],cp*r[1]-sp*r[2],sp*r[1]+cp*r[2]}};return {{cy*t[0]+sy*t[2],t[1],-sy*t[0]+cy*t[2]}};}
}
std::uint32_t launchSeed(const std::string&round_id,Owner owner){return seed("turret-obstacle-v1|"+round_id+"|"+(owner.human?"player:":"bot:")+std::to_string(owner.id));}
Impulse launchImpulse(std::uint32_t value){constexpr double pi=3.14159265358979323846;std::uint32_t state=(value&0x7fffffffu);if(!state)state=1;const auto unit=[&](){state=(state*1664525u+1013904223u)&0x7fffffffu;return double(state)/2147483648.;};const auto between=[&](double low,double high){return low+(high-low)*unit();};const auto heading=between(-pi,pi),drift=between(1.5,4.5);Impulse out;out.velocity={{drift*std::sin(heading),10.5,drift*std::cos(heading)}};out.spin[0]=between(-2.6,2.6);out.spin[1]=between(1.1,2.6)*(unit()<.5?1.:-1.);out.spin[2]=between(1.1,2.6)*(unit()<.5?1.:-1.);return out;}
Flight resolveFlight(const Point&origin,const Point&initial_velocity,World&world,double clearance,double step,double limit,int deflections){
    finite(origin);finite(initial_velocity);if(!std::isfinite(clearance)||!std::isfinite(step)||!std::isfinite(limit))throw std::invalid_argument("Detached flight time is nonfinite");if(step<=0.)throw std::invalid_argument("Detached flight step must be positive");clearance=std::max(0.,clearance);limit=std::max(step,limit);deflections=std::max(0,deflections);Flight out;out.origin=origin;out.velocity=initial_velocity;auto part_origin=origin,part_velocity=initial_velocity,current=origin;double part_time=0.,elapsed_before=0.;
    while(elapsed_before+part_time<limit){const auto following=std::min(limit-elapsed_before,part_time+step);const auto next=position(part_origin,part_velocity,following);auto start=current,end=next;start[1]-=clearance;end[1]-=clearance;const auto contact=world.collide(start,end);if(!contact){current=next;part_time=following;continue;}const auto point=contact->point;finite(point);const auto dx=next[0]-current[0],dy=next[1]-current[1],dz=next[2]-current[2],length_sq=dx*dx+dy*dy+dz*dz;const auto fraction=length_sq<=0.?0.:std::clamp(((point[0]-current[0])*dx+(point[1]+clearance-current[1])*dy+(point[2]-current[2])*dz)/length_sq,0.,1.);const auto hit_time=part_time+(following-part_time)*fraction;const auto impact=velocity(part_velocity,hit_time);if(impact[1]>-.5&&deflections>0){--deflections;out.segments.push_back({part_origin,part_velocity,elapsed_before,part_time});elapsed_before+=part_time;part_origin=current;part_velocity={{0.,velocity(part_velocity,part_time)[1],0.}};part_time=0.;continue;}out.segments.push_back({part_origin,part_velocity,elapsed_before,hit_time});out.duration=elapsed_before+hit_time;out.contact=point;out.rest={{point[0],point[1]+clearance,point[2]}};out.impact_velocity=impact;out.energy=energy(impact);out.landed=true;return out;}
    out.segments.push_back({part_origin,part_velocity,elapsed_before,part_time});out.duration=elapsed_before+part_time;out.rest=position(part_origin,part_velocity,part_time);out.impact_velocity=velocity(part_velocity,part_time);out.energy=energy(out.impact_velocity);return out;
}
Row freezeVisualPlan(Owner owner,const LaunchInput&input,std::uint32_t value,World&world){if(!input.geometry_ready||!input.exploded_models)throw std::invalid_argument("Detached launch geometry is unavailable");finite(input.position);finite(input.attitude);finite(input.mount);if(!std::isfinite(input.turret_yaw))throw std::invalid_argument("Detached launch yaw is nonfinite");const auto mount=transformed(input.mount,input.attitude);Point launch{};for(unsigned i=0;i<3;++i)launch[i]=input.position[i]+mount[i];const auto impulse=launchImpulse(value);Row row;row.owner=owner;row.attitude={{input.attitude[0]+input.turret_yaw,input.attitude[1],input.attitude[2]}};row.spin=impulse.spin;row.flight=resolveFlight(launch,impulse.velocity,world,input.clearance);return row;}
bool LaunchQueue::queue(Owner owner,const LaunchInput&input,double now,World&world){if(owner.id<1||owner.id>2147483647||accepted_.count(owner)||proposals_.count(owner)||accepted_.size()+proposals_.size()>=12)return false;const auto old=retries_.find(owner);if(old!=retries_.end()&&now<old->second)return false;if(old==retries_.end())retry_order_.push_back(owner);retries_[owner]=now+.25;try{proposals_[owner]=freezeVisualPlan(owner,input,launchSeed(round_id_,owner),world);return true;}catch(const std::exception&e){failures.push_back({owner,e.what()});return false;}}
void LaunchQueue::retry(double now,LaunchSource&source,World&world){const auto keys=retry_order_;for(const auto owner:keys){if(accepted_.count(owner)||proposals_.count(owner)||now<retries_.at(owner))continue;try{auto input=source.lookup(owner);if(input&&input->ready&&input->detached)queue(owner,*input,now,world);}catch(const std::exception&e){failures.push_back({owner,e.what()});}}}
bool LaunchQueue::accept(const Row&row){auto found=accepted_.find(row.owner);if(found!=accepted_.end()&&row.motion_sequence<=found->second.motion_sequence)return false;if(found==accepted_.end()&&accepted_.size()>=12)return false;accepted_[row.owner]=row;auto pending=proposals_.find(row.owner);if(pending!=proposals_.end()&&pending->second.motion_sequence<=row.motion_sequence)proposals_.erase(pending);return true;}
void LaunchQueue::proposal(Row row){proposals_[row.owner]=std::move(row);}
std::vector<Row> LaunchQueue::rows()const{auto all=accepted_;for(const auto&entry:proposals_)all[entry.first]=entry.second;std::vector<std::pair<std::string,Row>> sorted;for(const auto&entry:all)sorted.push_back({std::string(entry.first.human?"player:":"bot:")+std::to_string(entry.first.id),entry.second});std::sort(sorted.begin(),sorted.end(),[](const auto&a,const auto&b){return a.first<b.first;});std::vector<Row> out;for(const auto&entry:sorted)out.push_back(entry.second);return out;}
}
